mapper.select:
select fp.FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fpi.ISSUE_PRICE, fp.COUPON_SPECIES, fpi.INT_TYPE, case when fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '02' then sdl_sd.ITEM_VALUE|| '+'|| nvl(fpi.BP, 0) end referenceRateStr/*,当带入资产的息票品种为附息-浮动利率时，显示字段参考收益率*/, case when fp.COUPON_SPECIES in ('02', '03') then fpi.REFER_YIELD end referenceRate/*当带入资产的息票品种为零息/贴现时，显示字段参考收益率*/, case when (fp.COUPON_SPECIES = '01' and fpi.INT_TYPE = '01') or fp.COUPON_SPECIES = '04' then fpi.REFER_YIELD end rate/*当带入资产的息票品种为利随本清/附息-固定利率时，显示字段票面利率*/, eed.ENTRUST_ID, eed.PORTFOLIO_ID, pp.PORTFOLIO_NAME, nvl(eed.ENTRUST_NUM*100, 0) - nvl(bobp.SUBSCRIPTION_AMOUNT,0) avaNum, nvl(eed.ENTRUST_NUM*100, 0) - nvl(bobp.SUBSCRIPTION_AMOUNT,0) SUBSCRIPTION_AMOUNT, eed.INV_AIM, eed.SEC_ACCT_ID, ssai.SEC_ACCT_NAME, IPAR.PARTY_ID, (select distinct TRADER_ID from MST_CFETS_CUSTOMER_TRADER mcct inner join SYS_USER su on mcct.TRADER_ID = su.SSO_USER_ID where USER_NAME = #{loginUserId}) OUR_TRADER from FIN_PRODUCT fp left join FIN_PRODUCT_ISSUE fpi on fp.FINPROD_ID = fpi.FINPROD_ID left join SYS_DATADICT_LIST sdl_sd on sdl_sd.DICT_CODE = 'SECRATE_DATA' and sdl_sd.ITEM_CODE = fpi.INT_RATE_ID left join ETR_ENTRUST ee on ee.FINPROD_ID = fp.FINPROD_ID left join ETR_ENTRUST_DETAIL eed on eed.ENTRUST_ID = ee.ENTRUST_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = eed.PORTFOLIO_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA IPAR ON eed.PORTFOLIO_ID = IPAR.PORTFOLIO_ID AND IPAR.CFETS_ACCT_TYPE = '01' left join STL_SEC_ACCT_INFO ssai on ssai.SEC_ACCT_ID = eed.SEC_ACCT_ID left join (select sum(SUBSCRIPTION_AMOUNT) SUBSCRIPTION_AMOUNT, ENTRUST_ID, PORTFOLIO_ID from BID_ORDER_BID_PRICE where IS_CANCEL = 'N' and TRADE_STATUS != '03' and BID_PRICE = 99999999 group by ENTRUST_ID, PORTFOLIO_ID) bobp on bobp.ENTRUST_ID = eed.ENTRUST_ID and eed.PORTFOLIO_ID = bobp.PORTFOLIO_ID
#{item}
